<?php
declare(strict_types=1);
return new class implements ToolCallingProviderAdapter {
 private function baseUrl(array $p):string{$url=rtrim(trim((string)($p['base_url']??'http://127.0.0.1:11434')),'/');if(!filter_var($url,FILTER_VALIDATE_URL)||!in_array(parse_url($url,PHP_URL_SCHEME),['http','https'],true))throw new InvalidArgumentException('Ollama base URL must be HTTP(S).');return $url;}
 private function call(string $url,array $payload=[],bool $post=false):stdClass{$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>4,CURLOPT_TIMEOUT=>120,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2]);if($post){curl_setopt($ch,CURLOPT_POST,true);curl_setopt($ch,CURLOPT_HTTPHEADER,['Content-Type: application/json']);curl_setopt($ch,CURLOPT_POSTFIELDS,json_encode($payload,JSON_UNESCAPED_UNICODE));}$raw=curl_exec($ch);$err=curl_error($ch);$code=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);if($raw===false)throw new RuntimeException('Ollama connection failed: '.$err);try{$d=json_decode($raw,false,64,JSON_THROW_ON_ERROR);}catch(JsonException $e){throw new RuntimeException('Ollama returned invalid JSON.',0,$e);}if(!$d instanceof stdClass)throw new RuntimeException('Ollama returned an invalid response object.');if($code<200||$code>=300){$detail=(string)($d->error??$raw);throw new RuntimeException('Ollama HTTP '.$code.': '.mb_substr($detail,0,700));}return $d;}
 public function models(array $p):array{$d=$this->call($this->baseUrl($p).'/api/tags');$models=$d->models??[];if(!is_array($models))throw new RuntimeException('Ollama models response has an invalid shape.');return array_map(static function($m):array{$m=$m instanceof stdClass?get_object_vars($m):(array)$m;$name=(string)($m['name']??'');return ['id'=>$name,'name'=>$name];},$models);}
 public function chat(array $p,string $model,array $messages):string{$payload=['model'=>$model,'messages'=>$messages,'stream'=>false,'options'=>['num_ctx'=>8192]];if(preg_match('/^qwen3(?::|$)/i',$model)===1)$payload['think']=false;$d=$this->call($this->baseUrl($p).'/api/chat',$payload,true);return (string)($d->message->content??'');}
 public function chatWithTools(array $p,string $model,array $messages,array $tools):ProviderToolCallResult{if(!array_is_list($tools)||count($tools)<1||count($tools)>64)throw new InvalidArgumentException('Ollama tool definitions must contain between 1 and 64 entries.');foreach($tools as $tool)if(!is_array($tool)||($tool['type']??'')!=='function'||!is_array($tool['function']??null)||!preg_match('/^[A-Za-z0-9_.-]{1,128}$/',(string)($tool['function']['name']??''))||!is_array($tool['function']['parameters']??null)||($tool['function']['parameters']['type']??'')!=='object')throw new InvalidArgumentException('Ollama tool definition is invalid.');$payload=['model'=>$model,'messages'=>$messages,'stream'=>false,'tools'=>$tools,'options'=>['num_ctx'=>8192]];if(preg_match('/^qwen3(?::|$)/i',$model)===1)$payload['think']=false;return ProviderToolCallResult::fromOllamaResponse($this->call($this->baseUrl($p).'/api/chat',$payload,true));}
};
